html {
    position: relative;
    min-height: 100%;
}

body {
    margin-bottom: 60px;
    background-color: #F4F3EF;
}

#welcome {
	padding: .5em;
	text-align: center;
	display: block;
}

#container {
	margin-bottom: 80px;
}

.footer {
    position: absolute;
    bottom: 0;
    width: 100%;
    background-color: white;
	font-size: small;
}

body > .container {
    padding: 25px 25px 25px 25px;
}

.navbar {
    background-color: white;
}

.footer > .container {
    padding: 15px;
}

.card-login {
	object-fit: cover;
	overflow: hidden;
	font-family: "object-fit: cover;";
}

@media (max-width: 768px) {
	.card-login {
		display: none;
	}
} 

.card-logo {
	object-fit: contain;
	font-family: "object-fit: contain;";
	padding-top: 1em;
	cursor: pointer;
}

.card-single {
	width: 100%;
	float: none;
	margin: 0px auto;
}

@media (min-width: 768px) {
	.card-single {
		width: 75%;
	}
} 

.card {
    min-width: 200px;
}

.navbar-nav .nav-link {
    padding-right: 10px;
    text-align: right;
}

.card-footer {
    background-color: white;
	border: none;
	padding-bottom: 1.5em;
}

.list-group-item {
	font-size: small;
	border: none;
	padding-bottom: 0;
}

.list-group {
	padding: 1em;
}

.card-title {
	font-weight: bold;
	font-size: large;
}

.btn {
	margin: 0px auto;
}

.rememberme {
	font-size: small;
}

.error {
	color: #EB362B;
}

span.selected {
	font-weight: bold !important;
}

a.more:link, a.more:visited, a.more:hover, a.more:active { 
	text-decoration: none;
}

#logo {
	height: 65px;
}

@media (max-width: 768px) {
	#logo {
		height: 30px;
	}
} 

#birthdate .row, #birthdate .row  .col {
	padding: 0;
}

#invalid, #required {
	display: none;	
}

button {
	cursor: pointer;
}

::-webkit-input-placeholder, .form-control::-webkit-input-placeholder {
  color: lightgray; 
  font-style: italic;
}

:-ms-input-placeholder, .form-control:-ms-input-placeholder {
  color: lightgray; 
  font-style: italic;
}

::placeholder, .form-control::placeholder {
  color: lightgray; 
  font-style: italic;
}

