/*========================= TOP OF THE MENU CASCADE =========================*/

.menu {
	position:relative;        /* establish a menu-relative positioning context */
	margin:0;
	padding:0;
	border:0;
	float: left;
	font-size:12px;         /* this (and also below) sets the menu's font size */
	overflow: visible;
}

.menu ul {
	z-index:10;
	padding:0;
	margin:0;
