	margin:-1px 0;              /* IE5 needs -1px top and bottom table margins */
	margin:0;               /* re-zero the table margins for everyone but IE5 */
	border-collapse:collapse;      /* IE5 needs this for the sub-menus to work */
	font-size:12px;        /* this sets the base font size for our entire menu */
}


.menu ul li ul li a {
    color: white;
}

.menu ul.leftmenu li ul li a {
    color: white;
}

/*======================== TOP LEVEL MENU DEFINITIONS ========================*/

.menu ul li ul {
	display:none;                  /* initially hide the entire list hierarchy */
	padding:1px;                               /* this is our box border width */
}

.menu ul li a,
.menu ul li span,
.menu ul li a:visited {                    /* unselected top-level menu items */
	display:block;
	float:left;
	text-decoration:none;
}

/*======================== 2ND LEVEL MENU DEFINITIONS ========================*/

.menu ul li ul {                           /* 2nd level drop-down box */
	z-index: 20;
	display:none;                  /* initially hide the entire list hierarchy */
	padding:1px;                               /* this is our box border width */
	margin:0;
	top: 22px;              /* place us just up underneath the top-level images */
	height:auto;      /* the drop-down height will be determiend by line count */
	color:white;                        /* this sets the unselected-text color */
}

.menu ul li ul.horizontal li {
    float: left;
    clear: none;
 	left: 5px;
}

.menu ul.horizontal li.vertical {
    display: block;
    clear: both;
}

.menu div.click li ul,
